@app.cell
def _(population, features, feature_selector, batch_selector, concentration_selector, outlier_selector, iqr_selector, np):
    feature_name = features[feature_selector.value]
    filtered = population
    if batch_selector.value != "Все":
        filtered = filtered[filtered.batch.eq(int(batch_selector.value))]
    if concentration_selector.value != "Все":
        filtered = filtered[np.isclose(filtered.concentration, float(concentration_selector.value))]

    n_pre = len(filtered)
    flagged = 0
    if n_pre >= 4:
        _q1, _q3 = np.quantile(filtered[feature_name], [0.25, 0.75])
        iqr = _q3 - _q1
        outside = ~filtered[feature_name].between(_q1 - iqr_selector.value * iqr, _q3 + iqr_selector.value * iqr)
        flagged = int(outside.sum())
        if outlier_selector.value == "Исключить IQR-флаги":
            filtered = filtered.loc[~outside]
    data_values = filtered[feature_name].to_numpy(dtype=float)
    return feature_name, filtered, data_values, n_pre, flagged


