@app.cell
def _(mo, data_values, interval_selector, np, go, make_subplots, stats, feature_selector):
    if len(data_values) < 4:
        render = mo.md("<div class='glass-card'>Для построения распределения увеличьте число наблюдений.</div>")
    else:
        counts, _edges = np.histogram(data_values, bins=int(interval_selector.value))
        mids = (_edges[:-1] + _edges[1:]) / 2
        width = _edges[1] - _edges[0]

        _fig = make_subplots(
            rows=2,
            cols=2,
            subplot_titles=[
                "Гистограмма · промышленные колонны",
                "Boxplot",
                "Эмпирическая функция распределения",
                "Q–Q относительно нормальной модели",
            ],
            vertical_spacing=0.15,
            horizontal_spacing=0.12,
        )
        _fig.add_trace(
            go.Bar(
                x=mids,
                y=counts,
                width=width * 0.82,
                marker=dict(color="#70b8ae", line=dict(color="#287a79", width=1.5)),
                name="Частота",
                customdata=np.stack([_edges[:-1], _edges[1:]], axis=1),
                hovertemplate="Интервал: %{customdata[0]:.3g} – %{customdata[1]:.3g}<br>n = %{y}<extra></extra>",
            ),
            row=1,
            col=1,
        )
        # Овальные крышки и блики для эффекта вертикальных технологических колонн.
        # ВАЖНО: высота каждой колонны остаётся равной реальной частоте.
        _ymax = max(1, int(counts.max()))
        for _mid, _count in zip(mids, counts):
            if _count <= 0:
                continue
            _fig.add_shape(
                type="rect", x0=float(_mid - width * 0.22), x1=float(_mid - width * 0.16),
                y0=0, y1=float(_count), fillcolor="rgba(231,255,246,.38)",
                line_width=0, row=1, col=1,
            )
            _fig.add_shape(
                type="circle", x0=float(_mid - width * 0.41), x1=float(_mid + width * 0.41),
                y0=float(_count - _ymax * .012), y1=float(_count + _ymax * .012),
                fillcolor="#b5e4d8", line=dict(color="#2f8581", width=1), row=1, col=1,
            )
        _fig.add_trace(go.Box(y=data_values, marker_color="#64a99e", line_color="#287a79", name="Отклик", boxpoints="outliers"), row=1, col=2)
        sorted_values = np.sort(data_values)
        _fig.add_trace(go.Scatter(x=sorted_values, y=np.arange(1, len(sorted_values) + 1) / len(sorted_values), mode="lines", line=dict(color="#277e79", width=2.6), name="ECDF"), row=2, col=1)
        qqx, qqy = stats.probplot(data_values, dist="norm", fit=False)
        _fig.add_trace(go.Scatter(x=qqx, y=qqy, mode="markers", marker=dict(size=4, color="#6bad9e"), name="Q–Q"), row=2, col=2)

        _fig.update_layout(
            template="plotly_white",
            height=820,
            margin=dict(l=40, r=20, t=78, b=40),
            showlegend=False,
            font=dict(family="Inter, Arial", color="#214e51"),
            paper_bgcolor="rgba(255,255,255,0)",
            plot_bgcolor="rgba(255,255,255,.93)",
            hovermode="closest",
        )
        _fig.update_annotations(font=dict(size=13, color="#164d4d"))
        _fig.update_xaxes(showgrid=True, gridcolor="#E0EFEB", zeroline=False)
        _fig.update_yaxes(showgrid=True, gridcolor="#E0EFEB", zeroline=False)
        _fig.update_xaxes(title="Отклик, усл. ед.", row=1, col=1)
        _fig.update_yaxes(title="Число измерений", row=1, col=1)
        _fig.update_xaxes(title="Отклик, усл. ед.", row=2, col=1)
        _fig.update_yaxes(title="Fₙ(x)", row=2, col=1)
        render = mo.vstack([
            mo.md(f"<div class='section-title'>03 / Распределение · {feature_selector.value}</div><div class='small-caption'>Здесь собраны четыре взаимодополняющих взгляда на распределение: частоты, boxplot, эмпирическая функция и Q–Q диаграмма.</div>"),
            mo.ui.plotly(_fig),
        ])
    render
    return


