@app.cell
def _(mo, population, features, feature_selector, sample_size, repetitions, sim_seed, np, go):
    values_full = population[features[feature_selector.value]].to_numpy(dtype=float)
    population_size = len(values_full)
    sample_n = min(int(sample_size.value), population_size)
    reps_n = int(repetitions.value)
    rng_sim = np.random.default_rng(int(sim_seed.value))
    without_replacement = np.array([rng_sim.choice(values_full, size=sample_n, replace=False).mean() for _ in range(reps_n)])
    with_replacement = np.array([rng_sim.choice(values_full, size=sample_n, replace=True).mean() for _ in range(reps_n)])
    _edges = np.histogram_bin_edges(np.r_[without_replacement, with_replacement], bins=22)
    _fig = go.Figure()
    _fig.add_histogram(x=without_replacement, xbins=dict(start=_edges[0], end=_edges[-1], size=_edges[1] - _edges[0]), name="Без возвращения", marker_color="#69b8ad", opacity=0.74)
    _fig.add_histogram(x=with_replacement, xbins=dict(start=_edges[0], end=_edges[-1], size=_edges[1] - _edges[0]), name="С возвращением", marker_color="#c18780", opacity=0.56)
    _fig.add_vline(x=float(np.mean(values_full)), line_dash="dash", line_color="#1a5154", annotation_text="Среднее N = 3009")
    _fig.update_layout(
        barmode="overlay",
        height=460,
        template="plotly_white",
        font=dict(family="Inter, Arial", color="#214e51"),
        xaxis_title="Выборочное среднее, усл. ед.",
        yaxis_title=f"Число выборок из {reps_n}",
        margin=dict(t=40, l=55, r=20, b=60),
        paper_bgcolor="rgba(255,255,255,0)",
        plot_bgcolor="rgba(255,255,255,.93)",
    )
    _fig.update_xaxes(showgrid=True, gridcolor="#E0EFEB", zeroline=False)
    _fig.update_yaxes(showgrid=True, gridcolor="#E0EFEB", zeroline=False)
    mo.vstack([
        mo.md(f"<div class='info-callout'>При <b>n = {sample_n}</b>: SD средних <b>без возвращения = {without_replacement.std(ddof=1):.3f}</b>; <b>с возвращением = {with_replacement.std(ddof=1):.3f}</b>. Обе оценки показаны для фиксированной совокупности <b>N = {population_size}</b>.</div>"),
        mo.ui.plotly(_fig),
    ])
    return


@app.cell
def _(mo):
    gen_method = mo.ui.dropdown(options=["Эмпирическая обратная CDF", "Нормальная обратная CDF", "Skew-normal"], value="Эмпирическая обратная CDF", label="Генератор")
    gen_n = mo.ui.slider(start=500, stop=10000, step=500, value=3000, label="Число псевдонаблюдений")
    gen_seed = mo.ui.slider(start=1, stop=999, step=1, value=42, label="Seed")
    mo.vstack([
        mo.md("<div class='section-title'>07 / Генератор на основе наблюдений</div><div class='section-note'>Интерактивно сравниваем реальные наблюдения с псевдонаблюдениями, построенными разными методами.</div>"),
        mo.hstack([gen_method, gen_n, gen_seed], gap=3),
    ])
    return gen_method, gen_n, gen_seed


@app.cell
def _(data_values, gen_method, gen_n, gen_seed, np, stats, mo, go):
    if len(data_values) < 4:
        result = mo.md("<div class='glass-card'>Не хватает наблюдений для подбора генератора.</div>")
    else:
        observed = data_values
        n_gen = int(gen_n.value)
        rng_gen = np.random.default_rng(int(gen_seed.value))
        u_vals = np.clip(rng_gen.random(n_gen), np.finfo(float).eps, 1 - np.finfo(float).eps)
        if gen_method.value == "Эмпирическая обратная CDF":
            synthetic = np.sort(observed)[np.minimum((u_vals * len(observed)).astype(int), len(observed) - 1)]
        elif gen_method.value == "Нормальная обратная CDF":
            synthetic = observed.mean() + observed.std(ddof=1) * stats.norm.ppf(u_vals)
        else:
            a_param, loc_param, scale_param = stats.skewnorm.fit(observed)
            synthetic = stats.skewnorm.ppf(u_vals, a_param, loc=loc_param, scale=scale_param)
        bins = np.histogram_bin_edges(np.r_[observed, synthetic], bins=36)
        _fig = go.Figure()
        _fig.add_histogram(x=observed, xbins=dict(start=bins[0], end=bins[-1], size=bins[1] - bins[0]), histnorm="probability density", name="Реальные наблюдения", marker_color="#70b8ae", opacity=0.8)
        _fig.add_histogram(x=synthetic, xbins=dict(start=bins[0], end=bins[-1], size=bins[1] - bins[0]), histnorm="probability density", name="Генератор", marker_color="#ba7d78", opacity=0.48)
        _fig.update_layout(
            barmode="overlay",
            height=460,
            template="plotly_white",
            font=dict(family="Inter, Arial", color="#214e51"),
            xaxis_title="Значение величины, усл. ед.",
            yaxis_title="Плотность",
            margin=dict(t=40, l=55, r=20, b=60),
            paper_bgcolor="rgba(255,255,255,0)",
            plot_bgcolor="rgba(255,255,255,.93)",
        )
        _fig.update_xaxes(showgrid=True, gridcolor="#E0EFEB", zeroline=False)
        _fig.update_yaxes(showgrid=True, gridcolor="#E0EFEB", zeroline=False)
        ks_stat = stats.ks_2samp(observed, synthetic).statistic
        result = mo.vstack([
            mo.md(f"<div class='info-callout'><b>Реальные:</b> среднее {observed.mean():.3f}, SD {observed.std(ddof=1):.3f}. <b>Генератор:</b> среднее {synthetic.mean():.3f}, SD {synthetic.std(ddof=1):.3f}. Двухвыборочная статистика KS = <b>{ks_stat:.3f}</b>. Это полезная проверка сходства, но не финальное доказательство качества генератора.</div>"),
            mo.ui.plotly(_fig),
        ])
    result
    return


@app.cell
def _(mo):
    mo.md(r"""
    <div class='section-title'>Математическая база и источники</div>
    <div class='section-note'>Формулы сохранены в LaTeX, чтобы критерий КТвД по математическому оформлению также был выполнен внутри интерактивного приложения.</div>

    Эмпирический метод:
    $$X^*=F_n^{-1}(U), \qquad U\sim\mathrm{Uniform}(0,1).$$

    Нормальное квантильное преобразование:
    $$X^*=\hat\mu+\hat\sigma\Phi^{-1}(U).$$

    Стандартизация:
    $$Z_i=\frac{X_i-\bar X}{s_X},\qquad
    s_X=\sqrt{\frac{\sum_i(X_i-\bar X)^2}{n-1}}.$$

    Методы описаны для конечной совокупности, доступной в исходном эксперименте.
    Обобщение на будущие измерения требует осторожности, поскольку на систему влияют время,
    концентрация и состав газа.

    **Источники:**
    [UCI Gas Sensor Array Drift](https://archive.ics.uci.edu/dataset/270/gas+sensor+array+drift+at+different+concentrations) ·
    [Vergara et al., Chemical gas sensor drift compensation using classifier ensembles](https://doi.org/10.1016/j.snb.2012.01.074)
    """)
    return


@app.cell
def _():
    # --- ВСТРОЕННЫЕ ФОТОГРАФИИ (служебный блок) ---
    # Преобразуем 3 изображения в безопасные локальные data URI.
    # Для редактирования статистики и дизайна этот блок изменять не требуется.
    _photo_data = {
        'industrial_hero.webp': '',
        'industrial_detail.webp': '',
        'industrial_pipe_detail.webp': '',
    }
    # Встраиваем фотографии как data:image/webp — без дополнительных файлов и путей.
    # Ссылки работают непосредственно внутри HTML-вывода marimo.
    photo_uris = {
        name: "data:image/webp;base64," + encoded
        for name, encoded in _photo_data.items()
    }
    return photo_uris

